<!-- ADP / Model & effort. Vue 3. No external UI dependencies.
     AI responses and workflow runs are local interactions; connect your own services.
     Listen for adp-navigate on the root to integrate your application router. -->
<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue';
const root = ref(null);
let cleanup;
onMounted(() => { cleanup = mountDemo(root.value); });
onBeforeUnmount(() => cleanup?.());
function mountDemo(root) {
  const cleanups = [];
  const timers = new Set();
  const intervals = new Set();
  const document = {
    querySelector: (s) => root.querySelector(s),
    querySelectorAll: (s) => root.querySelectorAll(s),
    createElement: (tag) => window.document.createElement(tag),
    addEventListener: (name, handler) => { root.addEventListener(name, handler); cleanups.push(() => root.removeEventListener(name, handler)); },
  };
  const setTimeout = (fn, ms) => { const id = window.setTimeout(() => { timers.delete(id); fn(); }, ms); timers.add(id); return id; };
  const setInterval = (fn, ms) => { const id = window.setInterval(fn, ms); intervals.add(id); return id; };
  const clearInterval = (id) => { window.clearInterval(id); intervals.delete(id); };
  const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
if($('#send')){$('#attach').onclick=()=>$('#file').click();$('#file').onchange=()=>$('#filename').textContent=$('#file').files[0]?.name||'Text & attachments';$('#send').onclick=()=>{let t=$('.composer textarea');if(!t.value.trim()){t.focus();return}$('#answer').hidden=false;$('#answer').textContent='Your idea: '+t.value.trim();$('#send').textContent='✓';};}
if($('#models')){$$('.segments button').forEach(b=>b.onclick=()=>{$$('.segments button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});$('#effort-note').textContent='Current effort: '+b.textContent});$$('.model-row').forEach(b=>b.onclick=()=>{$$('.model-row').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))})});}
if($('#play')){let timer,sec=0;function stop(){clearInterval(timer);$('.voice').classList.remove('playing');$('#play').textContent='▶';$('#voice-state').textContent='Playback paused';}$('#play').onclick=()=>{if($('.voice').classList.contains('playing'))return stop();if(sec>=24)sec=0;$('.voice').classList.add('playing');$('#play').textContent='Ⅱ';$('#voice-state').textContent='Exploring the waveform';timer=setInterval(()=>{sec++;$('#time').textContent='0:'+String(sec).padStart(2,'0')+' / 0:24';if(sec>=24)stop()},1000)};$('#restart').onclick=()=>{stop();sec=0;$('#time').textContent='0:00 / 0:24';};}
if($('#metric')){$$('.chart-bars button').forEach(b=>b.onclick=()=>{$$('.chart-bars button').forEach(x=>x.classList.toggle('selected',x===b));$('#metric').textContent=Number(b.dataset.value).toLocaleString();$('#chart-caption').textContent=b.getAttribute('aria-label')+' · '+Number(b.dataset.value).toLocaleString()+' people';});}
if($('#upload-file')){const drop=$('#drop');drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#upload-file').click()}};function show(f){if(!f)return;$('#upload-info').hidden=false;$('#upload-info').textContent=f.name+' · '+(f.size/1024).toFixed(1)+' KB';drop.querySelector('b').textContent='File selected';}$('#upload-file').onchange=()=>show($('#upload-file').files[0]);drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');show(e.dataTransfer.files[0])};}
if($('#note')){let history=[$('#note').value],index=0;function update(){let h=$('#history');h.max=history.length-1;h.value=index;$('#history-count').textContent=(index+1)+' / '+history.length+' versions';$('#undo').disabled=index===0;$('#redo').disabled=index===history.length-1;}$('#note').oninput=()=>{history=history.slice(0,index+1);history.push($('#note').value);index++;update()};function go(i){index=i;$('#note').value=history[index];update()}$('#undo').onclick=()=>go(Math.max(0,index-1));$('#redo').onclick=()=>go(Math.min(history.length-1,index+1));$('#history').oninput=e=>go(+e.target.value);}
if($('#popup-trigger')){let b=$('#popup-trigger'),m=$('#popup-menu');b.onclick=()=>{m.hidden=!m.hidden;b.setAttribute('aria-expanded',String(!m.hidden))};$$('#popup-menu button').forEach(x=>x.onclick=()=>{m.hidden=true;b.setAttribute('aria-expanded','false');$('#popup-result').textContent=x.dataset.message});document.addEventListener('keydown',e=>{if(e.key==='Escape'){m.hidden=true;b.setAttribute('aria-expanded','false');b.focus()}});document.addEventListener('click',e=>{if(!e.target.closest('.popup-demo')){m.hidden=true;b.setAttribute('aria-expanded','false')}});}
if($('#phrase-word')){let i=0,words=['idea','thought','detail','creation'];$('#phrase-word').onclick=()=>{$('#phrase-word').innerHTML=words[++i%words.length]+' <span>⌄</span>'};}
if($('#tasks')){let dragged;function count(){$('#task-count').textContent=$$('#tasks input:checked').length+' / 3'}$$('#tasks input').forEach(x=>x.onchange=count);$$('.move').forEach(x=>x.onclick=()=>{let row=x.closest('.task');let prev=row.previousElementSibling;if(prev)$('#tasks').insertBefore(row,prev)});$$('.task').forEach(x=>{x.ondragstart=()=>{dragged=x;x.style.opacity='.4'};x.ondragend=()=>x.style.opacity='1';x.ondragover=e=>e.preventDefault();x.ondrop=e=>{e.preventDefault();if(dragged&&dragged!==x)$('#tasks').insertBefore(dragged,x)}});}
if($('#halo-toggle'))$('#halo-toggle').onclick=()=>$('.halo-scene').classList.toggle('alt');
if($('#ring-range'))$('#ring-range').oninput=e=>{$('#ring-number').textContent=e.target.value;$('#ring-progress').setAttribute('stroke-dasharray',e.target.value+' 100')};
if($('#accept')){function decision(yes){$('.diff').classList.add('done');$('#diff-status').textContent=yes?'Accepted':'Dismissed';$('#diff-note').textContent=yes?'Copy updated':'Original copy retained';if(!yes){$('.plus').hidden=true;$('.minus').style.display='block'}$('#accept').disabled=true;$('#reject').disabled=true}$('#accept').onclick=()=>decision(true);$('#reject').onclick=()=>decision(false);}
$$('[data-scroll]').forEach(b=>b.onclick=()=>document.querySelector(b.dataset.scroll)?.scrollIntoView({behavior:'smooth'}));
  return () => { timers.forEach(window.clearTimeout); intervals.forEach(window.clearInterval); cleanups.forEach(fn => fn()); };
}
</script>

